//ui.r

library(shiny)
shinyUI(fluidPage(
  titlePanel("Store Name And There Date"),

  sidebarLayout(
    sidebarPanel(

      uiOutput("Box1"),
      uiOutput("Box2")
    ),
    mainPanel("Display results",
              tableOutput("view"))
  )
))

//server.r

library(shiny)
library(ggplot2)
df<- read.csv("reports.csv",header = TRUE,sep=",", stringsAsFactors=FALSE)

biz = data.frame(
  Sector =df$STR_NM,
  Stock = df$SALE_DATE,
  total = df$TOTAL,
  tri_id= df$TRI_ID,

  stringsAsFactors = FALSE
)

shinyServer(function(input, output) {

  output$Box1 = renderUI(selectInput("sector","select a storename",c(unique(biz$Sector),"pick one"),"pick one"))

  output$Box2 = renderUI(
    if (is.null(input$sector) || input$sector == "pick one"){return()
    }else selectInput("stock",
                      "Select a Date",
                      c(unique(biz$Stock[which(biz$Sector == input$sector)]),"pick one"),
                      "pick one")
  )

  subdata1 = reactive(biz[which(biz$Sector == input$sector),])
  subdata2 = reactive(subdata1()[which(subdata1()$Stock == input$stock),])

  output$view = renderTable({
    if(is.null(input$sector) || is.null(input$stock)){return()
    } else if (input$sector == "pick one" || input$stock == "pick one"){return()

    } else return(subdata2())
  })

})

Vasant,
I haven't tried it myself but that configuration does look reasonable.

I think a good next step would be to extract from nginx why exactly it is serving that 400. One way to do this is to configure logging at the info level, by replacing this line:

error_log /var/log/nginx/error.log warn;

with this one:

error_log /var/log/nginx/error.log info;

Then, reload nginx and reproduce the problem, and see if anything illuminating turns up in /var/log/nginx/error.log

Alan

